ALTER TABLE clinlims.inventory_item ADD COLUMN item_type VARCHAR(50);
UPDATE clinlims.inventory_item i
SET item_type = COALESCE((
    SELECT m.item_type
    FROM clinlims.inventory_item_tag t
    JOIN (VALUES ('reagent', 'REAGENT'), ('rdt', 'RDT'), ('cartridge', 'CARTRIDGE'),
                 ('hiv kit', 'HIV_KIT'), ('syphilis kit', 'SYPHILIS_KIT')) AS m (tag, item_type)
        ON m.tag = lower(t.tag)
    WHERE t.item_id = i.id
    ORDER BY m.item_type
    LIMIT 1), 'REAGENT');
ALTER TABLE clinlims.inventory_item ALTER COLUMN item_type SET NOT NULL;
ALTER TABLE clinlims.inventory_item ADD CONSTRAINT chk_item_type
    CHECK (item_type IN ('REAGENT', 'RDT', 'CARTRIDGE', 'HIV_KIT', 'SYPHILIS_KIT'));
CREATE INDEX idx_inventory_item_type ON clinlims.inventory_item (item_type);
